?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AI Chat</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@3.4.1/dist/css/bootstrap.min.css"></head><body><div class="container"><p><a href="index.php">← Dashboard</a></p><h1>Local AI Chat</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($answer):?><div class="panel panel-success"><div class="panel-heading">Local model response</div><div class="panel-body"><pre class="ai-answer"><?=e($answer)?></pre></div></div><?php endif;?><form method="post"><div class="form-group"><label>What do you want to practice?</label><textarea class="form-control" name="prompt" rows="6" placeholder="Example: Practice a 5-minute job interview with me."><?=e($prompt)?></textarea></div><button class="btn btn-primary">Ask local AI</button></form></div></body></html>
